"use client";

import { useSimulation } from "@/components/SimulationProvider";
import AuthPage from "@/app/auth/page";
import Sidebar from "@/components/Sidebar";
import Header from "@/components/Header";
import { Loader2, ShieldAlert } from "lucide-react";
import { usePathname } from "next/navigation";

export default function AppWrapper({ children }: { children: React.ReactNode }) {
    const { isAuthenticated, loading, currentUser } = useSimulation();
    const pathname = usePathname();

    const isAdminRoute = pathname.startsWith('/admin');
    const isUserAdmin = currentUser?.role === 'admin';

    if (loading) {
        return (
            <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center gap-4">
                <Loader2 className="animate-spin text-primary" size={40} />
                <p className="text-slate-500 font-black text-[10px] uppercase tracking-[0.3em] animate-pulse">Sincronizando Delta...</p>
            </div>
        );
    }

    if (!isAuthenticated) {
        return <AuthPage />;
    }

    if (isAdminRoute && !isUserAdmin) {
        return (
            <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center p-6 text-center">
                <div className="size-20 rounded-3xl bg-rose-500/10 text-rose-500 flex items-center justify-center mb-6 border border-rose-500/20">
                    <ShieldAlert size={40} />
                </div>
                <h1 className="text-2xl font-black text-white mb-2">Acesso Restrito</h1>
                <p className="text-slate-400 max-w-xs text-sm font-medium">Você não tem permissão para acessar a área administrativa. Entre em contato com o suporte se isso for um erro.</p>
                <button
                    onClick={() => window.location.href = '/'}
                    className="mt-8 px-8 py-3 bg-white text-slate-950 font-black rounded-2xl hover:bg-slate-100 transition-all"
                >
                    Voltar para o Início
                </button>
            </div>
        );
    }

    return (
        <div className="flex min-h-screen">
            <Sidebar />
            <main className="flex-1 lg:ml-64 min-h-screen flex flex-col w-full">
                <Header />
                <div className="flex-1 overflow-y-auto">
                    {children}
                </div>
            </main>
        </div>
    );
}
